    """Returns (P_o, P_e, excess, kappa) for one instance."""
    n_raters = len(samples)
    if n_raters <= 1:
        return (1.0, 0.0, 1.0, 1.0)

    entity_sets = []
    all_keys = set()
    for sample in samples:
        keys = extract_surface_keys(sample, subtask)
        entity_sets.append(keys)
